import {utfBytes, fruitSamples} from './worlds.mjs';
const wEsc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wBits = n => n.toString(2).padStart(8,'0');
function wb(type,label,value,disabled=false,pressed=null) {
  return `<button type="button" class="world-button" data-world="${type}"${value!==undefined?` data-value="${wEsc(value)}"`:''}${disabled?' disabled':''}${pressed!==null?` aria-pressed="${pressed}"`:''}>${label}</button>`;
}
const wForm=(type,label,value,placeholder='')=>`<form data-world-form="${type}" class="world-form"><label>${label}<input name="value" value="${wEsc(value)}" maxlength="${type==='command'?80:48}" placeholder="${wEsc(placeholder)}" autocomplete="off" spellcheck="false"></label><button class="world-button" type="submit">${type==='command'?'执行 ↵':'应用 ↵'}</button></form>`;
const wMeter=(n,max)=>`<div class="world-meter" role="img" aria-label="${n}/${max}">${Array.from({length:max},(_,i)=>`<i class="${i<n?'filled':''}"></i>`).join('')}</div>`;
const wCard=(label,body)=>`<div class="world-card"><span class="eyebrow">${label}</span>${body}</div>`;
const palette=['#f9f7e9','#263d33','#ce603e','#9baa55'];
export function renderLab(key,s) {
  let body='';
  switch(key) {
    case 'schedule': body=`<div class="ql-machine"><div class="ql-brand">sinclair <b>QL</b><span>◢ ◢ ◢</span></div><div class="world-duo">${s.counts.map((n,i)=>wCard(`任务 ${i?'B · 画画':'A · 写字'}`,`<div class="task-display">${i?Array.from({length:n},()=>'<span>▧</span>').join(''):'HELLO QL'.slice(0,n)||'▏'}</div>${wMeter(n,8)}${wb('pause',s.paused[i]?'▶ 恢复':'Ⅱ 暂停',i,false,s.paused[i])}`)).join('')}</div><div class="cpu-bus"><b>CPU</b><span>${s.last<0?'等待时钟':`这一拍 → 任务 ${s.last?'B':'A'}`}</span></div></div><div class="world-controls">${wb('tick','↻ 拨动时钟 · 一拍')}</div>`;break;
    case 'memory':body=`<div class="address-display"><span>地址 ADDRESS</span><strong>${s.address.toString(2).padStart(4,'0')}</strong><span>二进制 → ${s.address}</span></div><div class="memory-grid">${s.cells.map((n,i)=>`<button data-world="address" data-value="${i}" aria-pressed="${i===s.address}" aria-label="地址 ${i}，值 ${n}"><small>${i.toString(2).padStart(4,'0')}</small><b>${n}</b></button>`).join('')}</div><div class="world-controls"><label>要写的字节 <input class="byte-input" data-world-input="value" type="number" min="0" max="255" value="${s.value}"></label>${wb('write','写入 ↓')}${wb('read','读出 ↑')}</div><code class="big-code">${wBits(s.value)} = ${s.value}${s.value===65?' = A':''}</code>`;break;
    case 'branch':body=`<div class="robot-path" role="img" aria-label="机器人在第 ${s.position+1} 格，石头在第 4 格">${Array.from({length:7},(_,i)=>`<div class="${i===s.position?'robot-here':''}"><span>${i===s.position?'🤖':i===3?'◆':i===6?'⚑':'·'}</span><small>${i}</small></div>`).join('')}</div><div class="code-strip">${s.rule?'IF 前方是石头 → 跳跃<br>ELSE → 向前走':'向前走<br>向前走<br>向前走……'}</div><div class="world-controls">${wb('step','走一步 →',undefined,s.position===6)}${wb('rule',s.rule?'✓ 有石头就跳':'＋ 装上绕路规则',undefined,false,s.rule)}</div>`;break;
    case 'color':body=`<div class="world-controls">${wb('depth','1 bit · 黑白',1,false,s.depth===1)}${wb('depth','2 bit · 四色',2,false,s.depth===2)}</div><div class="color-studio"><div class="color-grid">${s.pixels.map((n,i)=>`<button style="background:${palette[n%(2**s.depth)]}" data-world="paint" data-value="${i}" aria-label="像素 ${i+1}，编码 ${n.toString(2).padStart(2,'0')}"></button>`).join('')}</div><div class="swatches">${palette.map((color,i)=>wb('select',`<i style="background:${color}"></i><code>${i.toString(2).padStart(2,'0')}</code><small>${['纸白','墨绿','橙色','叶绿'][i]}</small>`,i,false,s.selected===i)).join('')}</div></div><div class="byte-ribbon">${s.pixels.map(n=>`<code>${(n%(2**s.depth)).toString(2).padStart(s.depth,'0')}</code>`).join('')}</div><p class="world-hint">当前画笔：${['纸白','墨绿','橙色','叶绿'][s.selected]}。1 bit 模式只显示最低一位。</p>`;break;
    case 'cpu':body=`<div class="pc-case"><div class="pc-label">386 ERA <i></i> SLOW COMPUTER</div><div class="cpu-layout"><div class="instruction-list">${['LOAD 2','ADD 3','OUT','HALT'].map((line,i)=>`<div class="${s.pc===i?'active':''}"><span>${i}</span><code>${line}</code>${s.pc===i?'←':''}</div>`).join('')}</div><div class="registers">${wCard('程序计数器 PC',`<strong>${s.pc}</strong>`)}${wCard('小盒子 ACC',`<strong>${s.acc}</strong>`)}${wCard('屏幕 OUTPUT',`<strong>${s.output??'▏'}</strong>`)}</div></div><div class="phase-strip">${['① 取指','② 译码','③ 执行'].map((p,i)=>`<span class="${s.phase===i&&s.pc<4?'active':''}">${p}</span>`).join('')}</div></div><div class="world-controls">${wb('step',s.pc>=4?'✓ 程序结束':'↻ 拨动时钟',undefined,s.pc>=4)}</div>`;break;
    case 'drivers':body=`<div class="device-map">${wCard('程序',`<div class="device-value">${s.buffer||'等待输入'}</div>`)}<div class="os-bridge">操作系统</div><div class="world-duo">${['keyboard','disk'].map((k,i)=>`<div class="driver-path ${s[k]?'connected':''}"><div class="wire"></div>${wb('toggle',`${s[k]?'●':'○'} ${i?'磁盘':'键盘'}驱动`,k,false,s[k])}<div class="device-value">${i?'▣':'▤'}</div>${wb(i?'save':'key',i?'保存到磁盘':'按下 A')}<small>${i?`磁盘内容：${s.file||'空'}`:'KEYBOARD'}</small></div>`).join('')}</div></div>`;break;
    case 'files':body=`<div class="file-browser"><div class="file-tree">${s.dirs.map(d=>`<div>▱ ${wEsc(d)}</div>`).join('')}${Object.keys(s.files).map(f=>`<div>▤ ${wEsc(f)}</div>`).join('')}</div><div class="unix-terminal"><span>LINUX ERA · 小磁盘</span><pre>${wEsc(s.output.join('\n'))}</pre><b>${wEsc(s.cwd)} $ ▏</b></div></div>${wForm('command','输入文件命令','','write dream.txt HELLO')}<div class="world-controls command-presets">${['ls','cd notes','write dream.txt HELLO','cat dream.txt','cd ..'].map(c=>wb('command',`<code>${c}</code>`,c)).join('')}</div>`;break;
    case 'patch':body=`<div class="world-duo">${wCard('你的源码',`<pre class="source-code">function add(a, b) {<br>  return a <mark>${s.fixed?'+':'−'}</mark> b;<br>}</pre>${wb('fix',s.fixed?'换回减号':'把 − 改成 +')}`)}${wCard('朋友的副本',`<pre class="source-code">return a ${s.friendFixed?'+':'−'} b;</pre><div class="big-result">2 + 3 = ${s.friendFixed?5:-1}</div>`)}</div><div class="test-cases">${[[2,3],[0,1],[4,4]].map(([a,b])=>`<div><code>${a} + ${b} = ${s.tests===null?'?':s.fixed?a+b:a-b}</code><span>${s.tests===null?'待测试':s.fixed?'✓':'×'}</span></div>`).join('')}</div><div class="world-controls">${wb('test','▷ 跑 3 个测试')}${wb('share','分享这个修正 →',undefined,s.tests!==true)}</div>`;break;
    case 'modem': {
      const wave=s.bits.map((bit,i)=>{const count=bit?4:2;return Array.from({length:count*2+1},(_,j)=>`${i*50+j*50/(count*2)},${40+(j%2?20:-20)}`).join(' ');}).join(' ');
      body=`<div class="modem-box"><div class="modem-lights"><i></i><i></i><i></i><span>DATA / TELEPHONE LINE</span></div><div class="signal-bits">${s.bits.map((b,i)=>wb('flip',String(b),i,false,!!b)).join('')}</div><svg class="signal-wave" viewBox="0 0 400 80" role="img" aria-label="用两种频率表示 0 和 1 的教学波形"><polyline points="${wave}" fill="none" stroke="currentColor" stroke-width="2"/></svg><div class="world-controls">${wb('speed','1 bit/秒',1,false,s.speed===1)}${wb('speed','4 bit/秒',4,false,s.speed===4)}</div></div><div class="world-controls">${wb('send','发送这 8 个 bit →')}</div><div class="receiver"><span>另一端</span><code>${s.received?s.received.join(''):'????????'}</code><b>${s.received?s.sentSeconds+' 秒':'等待信号'}</b></div>`;break;
    }
    case 'packets':body=`<div class="packet-sender"><span class="eyebrow">发送端 · 一句话拆成四个包</span><div class="packet-grid">${['你好，','来自','过去的','电脑！'].map((word,i)=>`<div class="packet ${s.dropped.includes(i)?'lost':''}"><b>包 ${i+1}</b><strong>${word}</strong>${wb('deliver',s.received.includes(i)?'再送一次':'送达 ↓',i)}${wb('drop','丢在路上',i,s.received.includes(i))}</div>`).join('')}</div></div><div class="packet-arrivals">到达顺序：${s.arrivals.map(i=>`<b>${i+1}</b>`).join('')||'等待中'}${s.duplicates?` · 忽略 ${s.duplicates} 个重复包`:''}</div><div class="message-rebuild">${['你好，','来自','过去的','电脑！'].map((w,i)=>`<span class="${s.received.includes(i)?'received':''}">${s.received.includes(i)?w:'□'}</span>`).join('')}</div>`;break;
    case 'dns':body=`<div class="address-book"><div class="browser-bar">◎ <strong>${s.name}</strong></div><div class="world-controls">${['book.test','moon.test','missing.test'].map(n=>wb('name',n,n,false,s.name===n)).join('')}</div><div class="dns-flow">${wCard('名字',`<b>${s.name}</b>`)}<span>→ DNS →</span>${wCard('查到的地址',`<b>${s.address||'?'}</b>`)}</div><div class="world-controls">${wb('lookup','① 查询地址')}${wb('visit','② 访问服务器')}</div></div><div class="world-duo">${wCard('DNS 记录',`<code>book.test<br>${s.servers['book.test']}</code>`)}${wCard('你的缓存',`<code>${s.cache['book.test']||'空'}</code>`)}</div><div class="world-controls">${wb('move','让服务器搬家',undefined,s.moved)}${wb('expire','让缓存过期')}</div>`;break;
    case 'web':body=`${wForm('title','网页标题',s.title)}<div class="world-controls">${['/','/missing'].map(p=>wb('path',p==='/'?'首页 /':'试试不存在的地址',p,false,s.path===p))}${wb('request','请求页面 ↓')}</div><div class="mini-browser"><div class="browser-bar">← → <code>book.test${s.path}</code></div><div class="web-page">${s.loaded===null?'<p>浏览器还没收到页面。</p>':s.loaded==='/missing'?'<h2>404</h2><p>这扇门后面没有网页。</p>':s.loaded==='/moon'?'<span class="moon-art">☾</span><h2>欢迎来到月球</h2><p>这是另一张网页。</p>':`<h2>${wEsc(s.title)}</h2><p>你好，世界。</p>${wb('follow','去月球看看 →')}`}</div></div><details class="world-details"><summary>看看浏览器收到的 HTML</summary><pre>${wEsc(s.loaded==='/'?`<h1>${s.title}</h1>\n<p>你好，世界。</p>\n<a href="/moon">去月球看看</a>`:s.loaded==='/moon'?'<h1>欢迎来到月球</h1>':s.loaded?'<h1>404</h1>':'等待请求')}</pre></details>`;break;
    case 'touch':body=`<div class="phone-stage"><div class="phone"><div class="phone-notch"></div><div class="touch-grid">${Array.from({length:16},(_,i)=>`<button data-world="tap" data-value="${i}" class="touch-app app-${Math.floor(i/4)} ${s.cell===i?'touched':''}" aria-label="${['相机','音乐','地图','便笺'][Math.floor(i/4)]}坐标 ${i%4},${Math.floor(i/4)}"><span>${['◉','♫','⌖','▤'][Math.floor(i/4)]}</span><small>${i%4},${Math.floor(i/4)}</small></button>`).join('')}</div><div class="phone-home"></div></div><div class="touch-readout"><span class="eyebrow">INPUT → EVENT → APP</span><strong>${s.cell===null?'(?, ?)':`(${s.cell%4}, ${Math.floor(s.cell/4)})`}</strong><p>${s.apps.length}/4 个应用已打开</p>${s.apps.map(a=>`<span class="app-badge">✓ ${a}</span>`).join('')}</div></div>`;break;
    case 'unicode': {
      const bytes=utfBytes(s.text);body=`${wForm('text','输入一个字，或一句话',s.text)}<div class="world-controls">${['A','你','🌱','é','👨‍👩‍👧'].map(t=>wb('text',t,t)).join('')}</div><div class="unicode-stats"><strong>${wEsc(s.text)||'空'}</strong><span>${[...s.text].length} 个码点<br>${bytes.length} 个字节 · ${bytes.length*8} bit</span></div><div class="byte-ribbon">${bytes.map((b,i)=>wb('byte',`<small>${i+1}</small><code>${b.toString(16).toUpperCase().padStart(2,'0')}</code>`,i,false,s.selected===i)).join('')}</div><div class="bit-inspector">${bytes.length?[...wBits(bytes[s.selected])].map((b,i)=>`<div class="${b==='1'?'on':''}"><small>${128>>i}</small><b>${b}</b></div>`).join(''):'输入文字，字节就会出现在这里。'}</div><p class="world-hint">${bytes.length?`选中的第 ${s.selected+1} 个字节 = ${bytes[s.selected]}。`:''}上面以十六进制显示字节。</p>`;break;
    }
    case 'cloud':body=`<div class="cloud-server"><span>☁ 远处的服务器 · v${s.server.rev}</span><strong>${wEsc(s.server.text)}</strong></div><div class="network-switch">${wb('online',s.online?'● 已联网 · 点此断开':'○ 已离线 · 点此连接',undefined,false,s.online)}</div><div class="world-duo">${['A','B'].map(d=>wCard(`设备 ${d} · 基于 v${s[d].base}`,`<div class="cloud-note">${wEsc(s[d].text)}<small>${s[d].dirty?'有本地修改':'已同步'}</small></div>${wb('edit','修改这份星星',d)}${wb('sync','同步 ↕',d)}`)).join('')}</div>${s.conflict?`<div class="conflict-box"><strong>两个版本冲突了</strong><p>选一份保留，另一份会被这份替换。</p><div class="world-controls">${wb('resolve','保留 A 的版本','A',!s.online)}${wb('resolve','保留 B 的版本','B',!s.online)}</div></div>`:''}`;break;
    case 'learn':body=`<div class="world-controls"><span>先拿一个标签：</span>${wb('label','● 圆果','round',false,s.label==='round')}${wb('label','▰ 长果','long',false,s.label==='long')}</div><div class="fruit-grid">${fruitSamples.map((f,i)=>{const tagged=s.samples.find(x=>x.shape===f.shape);return `<button data-world="sample" data-value="${i}" aria-label="形状 ${f.shape}，${tagged?(tagged.label==='round'?'圆果':'长果'):'未标注'}"><i style="width:${28+f.shape*3}px;border-radius:${50-f.shape*3}%"></i><small>形状值 ${f.shape}</small><b>${tagged?(tagged.label==='round'?'● 圆果':'▰ 长果'):'＋ 贴标签'}</b></button>`;}).join('')}</div><div class="new-fruit"><i></i><div><span>新形状 · 形状值 7</span><strong>${s.prediction?(s.prediction==='round'?'猜：圆果':'猜：长果'):'它会猜什么？'}</strong></div></div><div class="world-controls">${wb('test','让机器猜一猜',undefined,!s.samples.length)}</div>`;break;
    case 'message':body=`${wForm('text','你的最后一条消息',s.text)}<div class="message-pipeline">${['输入','编码','网络','磁盘','显示'].map((n,i)=>`<span class="${[true,s.encoded,s.sent,!!s.stored,s.opened][i]?'active':''}">${n}</span>`).join('')}</div><div class="world-controls">${wb('encode','① 编成字节',undefined,!s.text)}${wb('send','② 发出小包',undefined,!s.encoded||!s.chunks.length)}</div><div class="final-packets">${s.chunks.map((bytes,i)=>wb('deliver',`<b>包 ${i+1} ${s.received.includes(i)?'✓':'↓'}</b><code>${bytes.map(wBits).join('<br>')}</code>`,i,!s.sent,s.received.includes(i))).join('')}</div><div class="world-controls">${wb('store','③ 按序保存到磁盘',undefined,!s.sent)}${wb('open','④ 打开消息',undefined,!s.stored)}</div><div class="message-destination"><span>另一端的屏幕</span><strong>${s.opened?wEsc(new TextDecoder().decode(new Uint8Array(s.stored))):'▏'}</strong></div>${s.opened?'<div class="final-discovery">✳ 从 READY. 到这里，每一步都是你亲手完成的。</div>':''}`;break;
  }
  return `<div class="world-world" data-world-key="${key}">${body}<p class="world-feedback ${s.done?'success':''}" role="status">${s.done?'✓ ':''}${wEsc(s.feedback)}</p><div class="world-bottom"><span>${s.done?'这一个发现，已收入手记。':'可以慢慢试，也可以重新来。'}</span><button class="text-button" data-world-reset>↺ 重置本实验</button></div></div>`;
}
